#!/usr/bin/env python3
# Some portions generated by Codex. All JVM threads; nearest categories are sampled stacks, not wall time.
import json,pathlib,sys,collections
p=pathlib.Path(sys.argv[1]);events=json.loads(p.read_text())['recording']['events'];threads=collections.Counter();leaves=collections.Counter();inclusive=collections.Counter();tl=collections.Counter();tlmethods=collections.Counter();stacks=collections.Counter();cats=collections.Counter();native=collections.Counter();alloc=collections.Counter();java=0;tlcount=0;route=collections.Counter()
patterns=[('binary_writer',('BinaryQueryResultWriter',)),('binary_parser',('BinaryQueryResultParser',)),('workbench_ndjson',('WorkbenchPageResultWriter','WorkbenchTupleResultWriter','WorkbenchQueryProtocol')),('transport_mapping',('BNodeOriginTransport',)),('snapshot_binding',('CompactBindingSetSnapshot','MapBindingSet','BindingSet')),('memo_values',('NativeValueMemo','NativeValueCodec','ValueStore','LmdbLiteral','LmdbIRI')),('cancellation',('Cancellation','ProbeDeadline')),('lifetime_read_replay',('RepositoryValueIteration','ValueResolutionScope','ReadExposureScope','QueryExecutionContext','LmdbStoreConnection','ReadResourceContext')),('kernel',('LmdbNative','Kernel','RowState')),('logging',('logback','slf4j'))]
for event in events:
 typ=event.get('type','');v=event['values'];frames=(v.get('stackTrace') or {}).get('frames',[]);names=[]
 for f in frames:
  m=f.get('method') or {};names.append(((m.get('type') or {}).get('name','?')+'.'+m.get('name','?')).replace('/','.'))
 if typ.endswith('ObjectAllocationSample'):
  cls=v.get('objectClass') or {};alloc[cls.get('name','?')]+=v.get('weight',0);continue
 if not names:continue
 if typ.endswith('NativeMethodSample'):native[names[0]]+=1;continue
 if not typ.endswith('ExecutionSample'):continue
 java+=1
 if any('TupleResultBuilder.queryResultValues' in n or 'WorkbenchPageResultWriter.tryOrderedQueryValues' in n for n in names):route['orderedAdapterStackSamples']+=1
 if any('TupleResultBuilder.result' in n for n in names) and any('QueryBindingSet.getValue' in n or 'QueryBindingSet.addBinding' in n or 'QueryBindingSet.setBinding' in n for n in names):route['legacyMapRoundtripStackSamples']+=1
 if any('TupleResultBuilder.queryResultValues' in n or 'WorkbenchPageResultWriter.tryOrderedQueryValues' in n for n in names) and any('QueryBindingSet.getValue' in n or 'QueryBindingSet.addBinding' in n or 'QueryBindingSet.setBinding' in n for n in names):route['orderedStackWithQueryBindingSetSamples']+=1
 thread=v.get('sampledThread') or v.get('eventThread') or {};threads[thread.get('javaName','?')]+=1;leaves[names[0]]+=1;inclusive.update(set(names));stacks[' <- '.join(names[:16])]+=1
 category='container_jdk_other'
 for name in names:
  found=next((label for label,pats in patterns if any(pat in name for pat in pats)),None)
  if found:category=found;break
 cats[category]+=1
 if any(n.startswith('java.lang.ThreadLocal') for n in names):
  tlcount+=1;i=next(i for i,n in enumerate(names) if n.startswith('java.lang.ThreadLocal'));tl[next((n for n in names[i:] if not n.startswith('java.lang.ThreadLocal')),'truncated')]+=1;tlmethods.update(n for n in set(names) if n.startswith('java.lang.ThreadLocal'))
out={'warning':'Java ExecutionSample across all JVM threads only; nearest categories exclusive, inclusive frame counts overlap; neither wall time nor exact calls. Native samples separate; Node/client CPU absent. Allocation weights sampled, not exact bytes.','javaSamples':java,'actualAdapterRouteSamples':route,'threadLocalVisibleSamples':tlcount,'threadNames':threads,'nearestCategories':cats,'threadLocalCallers':dict(tl.most_common()),'threadLocalMethods':dict(tlmethods.most_common()),'topLeaves':leaves.most_common(40),'topInclusiveFrames':inclusive.most_common(60),'topStacks':stacks.most_common(40),'nativeSamples':sum(native.values()),'nativeTopLeaves':native.most_common(20),'sampledAllocationWeight':sum(alloc.values()),'sampledAllocationTopClasses':alloc.most_common(20)}
print(json.dumps(out,indent=2))
